 93	    private void registerErrorHandling() {
 94	        server.exception(HotelException.class, (exception, ctx) -> {
 95	            ctx.status(httpStatus(exception.errorCode()));
 96	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
 97	        });
 98	    }
 99	
100	    private static int httpStatus(ErrorCode errorCode) {
101	        return switch (errorCode) {
102	            case INVALID_REQUEST -> 400;
103	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
104	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
105	            case CAPACITY_EXCEEDED -> 422;
106	        };
107	    }
108	
109	    private static NewReservation readNewReservation(Context ctx) {
110	        CreateReservationRequest body;
111	        try {
112	            body = ctx.bodyAsClass(CreateReservationRequest.class);
113	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
114	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
115	        }
116	        if (body == null
117	                || body.roomNumber() == null
118	                || isBlank(body.guestName())
119	                || isBlank(body.guestEmail())
120	                || body.checkIn() == null
121	                || body.checkOut() == null
122	                || body.guests() == null
123	                || body.ratePlan() == null) {
124	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
125	        }
126	        boolean hasCpf = !isBlank(body.guestCpf());
127	        boolean hasCompany = !isBlank(body.companyCnpj()) || !isBlank(body.companyName());
128	        boolean hasPassport = !isBlank(body.guestPassport()) || !isBlank(body.guestCountry());
129	
130	        int identificationCount = (hasCpf ? 1 : 0) + (hasCompany ? 1 : 0) + (hasPassport ? 1 : 0);
131	        if (identificationCount != 1) {
132	            throw new HotelException(ErrorCode.INVALID_REQUEST,
133	                    "provide either guestCpf, or companyCnpj and companyName, or guestPassport and guestCountry");
134	        }
135	
136	        if (hasCompany && (isBlank(body.companyCnpj()) || isBlank(body.companyName()))) {
137	            throw new HotelException(ErrorCode.INVALID_REQUEST, "companyCnpj and companyName must both be provided");
138	        }
139	
140	        if (hasPassport && (isBlank(body.guestPassport()) || isBlank(body.guestCountry()))) {
141	            throw new HotelException(ErrorCode.INVALID_REQUEST, "guestPassport and guestCountry must both be provided");
142	        }
143	
144	        Guest guest = new Guest(
145	                body.guestName(),
146	                body.guestEmail(),
147	                body.guestCpf(),
148	                body.companyCnpj(),
149	                body.companyName(),
150	                body.guestPassport(),
151	                body.guestCountry());
152	        return new NewReservation(
153	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
154	    }
155	
156	    private static long reservationId(Context ctx) {
157	        String id = ctx.pathParam("id");
158	        try {
159	            return Long.parseLong(id);
160	        } catch (NumberFormatException notANumber) {
161	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
162	        }
163	    }
164	
165	    private static LocalDate readDate(Context ctx) {
166	        String date = requiredQueryParam(ctx, "date");
167	        try {
168	            return LocalDate.parse(date);
169	        } catch (DateTimeParseException badDate) {
170	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
171	        }
172	    }
173	
174	    private static YearMonth readMonth(Context ctx) {
175	        String month = requiredQueryParam(ctx, "month");
176	        try {
177	            return YearMonth.parse(month);
178	        } catch (DateTimeParseException badMonth) {
179	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
180	        }
181	    }
182	
183	    private static String requiredQueryParam(Context ctx, String name) {
184	        String value = ctx.queryParam(name);
185	        if (value == null) {
186	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
187	        }
188	        return value;
189	    }
190	
191	    private static boolean isBlank(String text) {
192	        return text == null || text.isBlank();
193	    }
194	}

