130	        int identificationCount = (hasCpf ? 1 : 0) + (hasCompany ? 1 : 0) + (hasPassport ? 1 : 0);
131	        if (identificationCount != 1) {
132	            throw new HotelException(ErrorCode.INVALID_REQUEST,
133	                    "provide either guestCpf, or companyCnpj and companyName, or guestPassport and guestCountry");
134	        }
135	
136	        if (hasCompany && (isBlank(body.companyCnpj()) || isBlank(body.companyName()))) {
137	            throw new HotelException(ErrorCode.INVALID_REQUEST, "companyCnpj and companyName must both be provided");
138	        }
139	
140	        if (hasPassport && (isBlank(body.guestPassport()) || isBlank(body.guestCountry()))) {
141	            throw new HotelException(ErrorCode.INVALID_REQUEST, "guestPassport and guestCountry must both be provided");
142	        }
143	
144	        Guest guest = new Guest(
145	                body.guestName(),
146	                body.guestEmail(),
147	                body.guestCpf(),
148	                body.companyCnpj(),
149	                body.companyName(),
150	                body.guestPassport(),
151	                body.guestCountry());
152	        return new NewReservation(
153	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
154	    }
